:root{--red:#a5221e;--darkred:#781b18;--blue:#11253c;--lightblue:#376fdc;--beige:#e3cc94;--black:#1e1b1b;--white:#fff;--darkgrey:#4c4c4c;--medgrey:#ddd;--lightgrey:#f4f4f5;--font-body:'Raleway',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;--font-heading:'Libre Baskerville',serif}.stacksbowers{display:flex;flex-direction:column;width:100%;max-width:1440px;margin:0 auto}.woocommerce ul.products{display:table}.woocommerce ul.products li.product .woocommerce-loop-product__title{font-size:14px}.woocommerce ul.products li.product .woocommerce-loop-product__title{font-size:14px;text-overflow:ellipsis;overflow:hidden;display:-webkit-box !important;-webkit-line-clamp:3;-webkit-box-orient:vertical;padding:0}.woocommerce-loop-product__title{color:var(--black)}.site-main{margin:1em}.woocommerce-breadcrumb{padding:.875em}.stock.out-of-stock{visibility:hidden}.woocommerce .button.product_type_simple{font-size:1.6rem;font-weight:700;font-family:var(--font-body);text-transform:uppercase;color:var(--white);background:var(--red);padding:1.15rem;display:block;line-height:1.7rem;border-radius:5px;letter-spacing:2px;transition:all .3s}.woocommerce .button.product_type_simple:hover{background:#781b18;color:var(--white)}.woocommerce ul.products li.product .price,.price{font-size:2em;color:var(--red);padding:10px 0}.product_meta *{color:#fff}.posted_in a{color:#fff}.sku_wrapper{color:#fff}.woocommerce-breadcrumb{visibility:hidden}.woocommerce-products-header{visibility:hidden}.wc-tabs{display:none}.woocommerce-tabs .panel{width:100%}.product-column-container{display:flex;width:100%}.woocommerce-product-details__short-description p{padding-top:1em}.product-column-1{flex-shrink:0;flex-basis:40%}.box{padding:10px;margin:1rem}.product_popup{position:relative;display:inline-block;cursor:pointer;-webkit-user-select:none;-moz-user-select:none;-ms-user-select:none;user-select:none}.product_popup .popup_title{visibility:hidden;width:160px;background-color:#555;color:#fff;text-align:center;border-radius:6px;padding:8px 0;position:absolute;z-index:1;bottom:125%;left:50%;margin-left:-80px}.product_popup .popup_title:after{content:"";position:absolute;top:100%;left:50%;margin-left:-5px;border-width:5px;border-style:solid;border-color:#555 transparent transparent}.product_popup .show{visibility:visible;-webkit-animation:fadeIn 1s;animation:fadeIn 1s}@-webkit-keyframes fadeIn{from{opacity:0}to{opacity:1}}@keyframes fadeIn{from{opacity:0}to{opacity:1}}.update-products-li{clear:none !important;margin-left:1% !important;margin-right:1% !important;width:22% !important}.update-products-li-column2{margin-left:2% !important;margin-right:2% !important;width:44% !important}.update-products-btn{width:50%;margin:0 auto !important}.update-products-popup{width:50%}@media only screen and (max-width:900px){.product-column-container{flex-direction:column}.woocommerce .button.product_type_simple{font-size:1.3rem}}#lightgallery{--grid-layout-gap:3px;--grid-column-count:4;--grid-item--min-width:100px;--gap-count:calc(var(--grid-column-count) - 1);--total-gap-width:calc(var(--gap-count) * var(--grid-layout-gap));--grid-item--max-width:calc((100% - var(--total-gap-width)) / var(--grid-column-count));display:grid;place-self:center;grid-template-columns:repeat(auto-fill,minmax(max(var(--grid-item--min-width), var(--grid-item--max-width)), 1fr));grid-gap:var(--grid-layout-gap)}.woocommerce-product-gallery__image{margin:auto;text-align:center}.product-column-1 .sbg-direct-inquiry{display:flex;align-items:center;justify-content:center;margin-bottom:1em}.product-column-2 .sbg-direct-inquiry{display:flex;align-items:left;justify-content:left;margin-bottom:1em}.product-column-2 .sbg-direct-inquiry .button-link{text-transform:uppercase;color:var(--red);background:0 0;padding:0;display:block;line-height:1.7rem;border-radius:5px;letter-spacing:2px;transition:all .3s}.product-column-2 .sbg-direct-inquiry .button-link:hover{color:#000;background:0 0;padding:0;displa